// wsrod uzywanych envow pokoi albo kluczy kolorow z pliku. Czysta funkcja
// danych — ta sama mapa daje zawsze ten sam wynik.
const ARKADIA_SIGNATURE_ENVS = Object.keys(ARKADIA_ENVS).map(Number).filter(k => k > 255);
function isArkadiaMap(map, filename) {
  if (!map || typeof map !== 'object') return false;
  const ud = (map.meta && map.meta.user_data) || {};
  if (ud.map_sync_version !== undefined) return true;
  if (/arkadia/i.test(String(ud.map_name || '') + ' ' + String(filename || ''))) return true;
  const sig = new Set(ARKADIA_SIGNATURE_ENVS);
  const seen = new Set();
  let hits = 0;
  const bump = (k) => {
    k = Number(k);
    if (!sig.has(k) || seen.has(k)) return false;
    seen.add(k);
    return ++hits >= 2;
  };
  const cols = map.colors || {};
  for (const k of Object.keys(cols.custom_env_colors || {})) if (bump(k)) return true;
  for (const k of Object.keys(cols.env_colors || {})) if (bump(k)) return true;
  for (const a of map.areas || []) for (const r of a.rooms || []) if (bump(r.env)) return true;
  return false;
}


