// ─────────────────────────────────────────────────────────────────────────────
// QSet<QString> — używany w v21+ dla mSpecialExitLocks
// ─────────────────────────────────────────────────────────────────────────────
function readQSetS(r) {
  const n = r.readUInt32();
  const s = new Set();
  for (let i = 0; i < n; i++) s.add(readQString(r));
  return s;
}

